import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"CDS Squid: BlueStore","description":"","frontmatter":{"title":"CDS Squid: BlueStore","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","BlueStore","Distributed Storage","Performance Optimization","Storage Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_BlueStore.md","filePath":"posts/2023/CDS_Squid_-_BlueStore.md","lastUpdated":1780459816000}'),a={name:"posts/2023/CDS_Squid_-_BlueStore.md"};function r(u,l,s,n,d,h){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="ceph-bluestore-会议纪要" tabindex="-1">Ceph BlueStore 会议纪要 <a class="header-anchor" href="#ceph-bluestore-会议纪要" aria-label="Permalink to &quot;Ceph BlueStore 会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 未提及</li><li><strong>参会人员</strong>: Eager, Adam, Igor 等（Mark 未能参加）</li><li><strong>议程</strong>: 讨论Ceph BlueStore的关键议题，包括分配器模拟器、碎片化处理、弹性共享Blob、Codel算法、自定义写前锁等。</li></ul><h4 id="主要讨论内容" tabindex="-1">主要讨论内容 <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容&quot;">​</a></h4><ol><li><p><strong>分配器模拟器</strong>：</p><ul><li>解决Booster中定位器问题，启动GSoC合作项目，开发分配器模拟器，预测分配器更改对部署后OSD的影响。</li></ul></li><li><p><strong>碎片化处理</strong>：</p><ul><li>在BlueStore中引入对象碎片整理的基本原语，创建空闲周期队列以进行碎片整理。</li></ul></li><li><p><strong>弹性共享Blob</strong>：</p><ul><li>引入弹性共享Blob特性，优化克隆对象时的效率，已回溯到Quincy和Reef版本，目前正在测试。</li></ul></li><li><p><strong>Codel算法</strong>：</p><ul><li>讨论Codel算法，旨在平衡延迟和吞吐量，通过批处理事务提高性能。</li></ul></li><li><p><strong>自定义写前锁</strong>：</p><ul><li>在BlueStore级别实现写前锁，减少写操作延迟，Igor已开发工程版本，需进一步完善。</li></ul></li><li><p><strong>政策与回溯</strong>：</p><ul><li>讨论代码重构和特性回溯的政策，提议在开发文档中建立高层次原则。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>推进分配器模拟器开发，并完善度量标准。</li><li>在BlueStore中实现碎片整理的基本原语。</li><li>继续测试和部署弹性共享Blob特性。</li><li>完善Codel算法和自定义写前锁的实现。</li><li>创建回溯政策的文档。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>开发和测试分配器模拟器。</li><li>在BlueStore中实现碎片整理的基本原语。</li><li>对弹性共享Blob特性进行进一步测试和部署。</li><li>完善Codel算法和自定义写前锁的实现。</li><li>创建回溯政策的文档。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议在预定时间内顺利结束，后续的CDS会议将在短时间内开始。</li></ul><h3 id="改进说明" tabindex="-1">改进说明 <a class="header-anchor" href="#改进说明" aria-label="Permalink to &quot;改进说明&quot;">​</a></h3><ul><li>在总结中增加了会议基本信息，并更详细地描述了每个讨论议题的内容。</li><li>保留了所有提到的Ceph相关关键词。</li><li>对原文中的部分内容进行了简化，使其更易于理解。</li></ul>',13)])])}const _=e(a,[["render",r]]);export{S as __pageData,_ as default};
